def run(inputs: dict) -> dict:
    import math

    metrics = inputs.get("ExtractedMetric", [])
    if not isinstance(metrics, list):
        raise ValueError("ExtractedMetric must be a list")

    # Собираем значения выручки, проверяя единицы и концепт
    values = []
    for m in metrics:
        if not isinstance(m, dict):
            continue
        if m.get("concept") != "SALES_REVENUE":
            continue
        sf = m.get("scalar_fact")
        if not isinstance(sf, dict):
            continue
        unit = sf.get("unit", "")
        if unit != "млн. руб.":
            raise ValueError(f"Unsupported unit: {unit}")
        values.append(sf["value"])

    if len(values) < 2:
        raise ValueError("Need at least 2 SALES_REVENUE values to calculate CV")

    n = len(values)
    mean = sum(values) / n
    variance_pop = sum((x - mean) ** 2 for x in values) / n
    std_pop = math.sqrt(variance_pop)
    cv = (std_pop / mean) * 100 if mean != 0 else 0.0

    return {
        "mean": mean,
        "std_pop": std_pop,
        "cv": cv
    }
